<?php
namespace App\Livewire\Documents;
use App\Models\Employee; use App\Models\EmployeeDocument; use App\Services\EmployeeDocumentService; use Livewire\Component; use Livewire\WithFileUploads;
class Index extends Component { use WithFileUploads; public ?int $employeeId=null;public string $category='contract';public string $expiresAt='';public string $notes='';public $file; public function upload(EmployeeDocumentService $s):void{$this->authorize('manage-hr');$d=$this->validate(['employeeId'=>'required|exists:employees,id','category'=>'required|string|max:80','expiresAt'=>'nullable|date','notes'=>'nullable|string|max:2000','file'=>'required|file|max:15360']);try{$s->store(Employee::findOrFail($d['employeeId']),$this->file,$d['category'],$d['expiresAt']?:null,auth()->id(),$d['notes']?:null);$this->reset('file','expiresAt','notes');}catch(\RuntimeException $e){$this->addError('file',$e->getMessage());}} public function delete(int $id,EmployeeDocumentService $s):void{$this->authorize('manage-hr');$s->delete(EmployeeDocument::findOrFail($id));} public function render(){return view('livewire.documents.index',['employees'=>Employee::orderBy('name')->get(),'documents'=>EmployeeDocument::with(['employee','uploader'])->latest()->limit(100)->get()]);} }
